import {federalTax,independentTaxes} from './financial-math.js?v=0.31.0';
// Educational cash-flow scenario. Prices are editable planning assumptions, not market quotes.
export const lifestyleSources={tax:'https://www.irs.gov/newsroom/working-families-tax-cuts-individuals-and-workers',retirement:'https://www.irs.gov/newsroom/401k-limit-increases-to-24500-for-2026-ira-limit-increases-to-7500',fica:'https://www.ssa.gov/pubs/EN-05-10003.pdf',medicare:'https://www.irs.gov/taxtopics/tc560',housing:'https://www.huduser.gov/portal/datasets/fmr.html',buying:'https://www.consumerfinance.gov/owning-a-home/',local:'https://livingwage.mit.edu/counties/48453',transit:'https://www.capmetro.org/fare/general-fares-overview/fares',texas:'https://comptroller.texas.gov/taxes/'};
export const austinRentContext={publisher:'HUD',period:'FY 2027',geography:'Austin–Round Rock–San Marcos metro',studio:1447,oneBedroom:1530,twoBedroom:1817,threeBedroom:2292,fourBedroom:2689,units:'monthly gross rent, including tenant-paid utilities except telephone, cable/satellite, and internet',sourceURL:'https://www.huduser.gov/portal/datasets/fmr/fmr2027/FY2027_FMR_Schedule.pdf',checkedAt:'2026-10-16'};
export const lifestyleNumeric=['weeklyHours','paidWeeks','businessExpenses','linkedLoanPayment','gross','manualNet','retirement','health','debt','extraNeeds','rent','utilities','homePrice','downPercent','mortgageRate','pmiRate','mortgageYears','propertyTax','homeInsurance','hoa','maintenance','cashSaved','carPrice','carDown','carRate','carMonths','fuel','carInsurance','carMaintenance','carOther','transit','rides','groceries','phone','household','saving','quickCount','quickPrice','casualCount','casualPrice','specialCount','specialPrice','travel','tripPrice','recreation','outingPrice','clothing','itemPrice'];
export function freshLifestyle(){return {weeklyHours:'40',paidWeeks:'52',businessExpenses:'0',linkedLoanPayment:'0',workMode:'employee',careerId:'',band:'custom',netMode:'estimate',housingMode:'rent',carMode:'used',notes:'',wageRelease:'austin-2026-10-16-v2',gross:'75000',manualNet:'',retirement:'8',health:'250',debt:'0',extraNeeds:'0',rent:'1350',utilities:'180',homePrice:'421000',downPercent:'20',mortgageRate:'7.40',pmiRate:'0.6',mortgageYears:'30',propertyTax:'2',homeInsurance:'250',hoa:'75',maintenance:'1',cashSaved:'0',carPrice:'22000',carDown:'4000',carRate:'11.19',carMonths:'60',fuel:'120',carInsurance:'180',carMaintenance:'100',carOther:'20',transit:'41.25',rides:'100',groceries:'400',phone:'125',household:'180',saving:'300',quickCount:'4',quickPrice:'20',casualCount:'2',casualPrice:'45',specialCount:'0',specialPrice:'100',travel:'150',tripPrice:'1200',recreation:'100',outingPrice:'25',clothing:'75',itemPrice:'40'};}
export function cleanLifestyle(raw){const p=freshLifestyle();if(!raw||typeof raw!=='object')return p;for(const key of lifestyleNumeric){const x=raw[key];if(typeof x==='string'||typeof x==='number')p[key]=String(x).slice(0,30);}for(const [key,values]of Object.entries({workMode:['employee','independent'],band:['custom','p25','median','p75','dallas','houston'],netMode:['estimate','manual'],housingMode:['rent','own'],carMode:['transit','paid','used','new']}))if(values.includes(raw[key]))p[key]=raw[key];p.wageRelease=typeof raw.wageRelease==='string'?raw.wageRelease:'';p.careerId=typeof raw.careerId==='string'?raw.careerId.slice(0,100):'';p.notes=typeof raw.notes==='string'?raw.notes.slice(0,2000):'';return p;}
export function loanPayment(principal,annualRate,months){if(principal===0)return 0;if(annualRate===0)return principal/months;const r=annualRate/1200;return principal*r/-Math.expm1(-months*Math.log1p(r));}
export function employeeTaxes(gross,retirementPercent=0){const retirement=gross*retirementPercent/100,federal=federalTax(Math.max(0,gross-retirement-16100)),social=Math.min(gross,184500)*.062,medicare=gross*.0145+Math.max(0,gross-200000)*.009;return {federal,social,medicare,retirement,monthly:(gross-retirement-federal-social-medicare)/12};}
export {independentTaxes};
export function calculateLifestyle(raw){const p=cleanLifestyle(raw);const active=['debt','extraNeeds','utilities','groceries','phone','household','saving','quickCount','quickPrice','casualCount','casualPrice','specialCount','specialPrice','travel','tripPrice','recreation','outingPrice','clothing','itemPrice',...(p.netMode==='manual'?['manualNet']:['gross','retirement','health','weeklyHours','paidWeeks','businessExpenses']),...(p.housingMode==='rent'?['rent']:['homePrice','downPercent','mortgageRate','pmiRate','mortgageYears','propertyTax','homeInsurance','hoa','maintenance','cashSaved']),...(p.carMode==='transit'?['transit','rides']:['fuel','carInsurance','carMaintenance','carOther',...(p.carMode==='paid'?[]:['carPrice','carDown','carRate','carMonths'])])];
 const n={},issues=[];for(const k of active){const v=Number(p[k]);if(p[k].trim()===''||!Number.isFinite(v)||v<0||v>10000000)issues.push(k);else n[k]=v;}
 for(const k of ['retirement','downPercent','mortgageRate','pmiRate','propertyTax','maintenance','carRate'])if(n[k]>100)issues.push(k);
 if(n.weeklyHours>168||n.paidWeeks>52)issues.push('paid hours or weeks');
 if(n.mortgageYears!==undefined&&(n.mortgageYears<1||n.mortgageYears>50))issues.push('mortgageYears');if(n.carMonths!==undefined&&(n.carMonths<1||n.carMonths>120))issues.push('carMonths');if(n.carDown>n.carPrice)issues.push('carDown');if(p.netMode==='estimate'&&Math.max(0,n.gross*n.weeklyHours/40*n.paidWeeks/52-(p.workMode==='independent'?n.businessExpenses*12:0))*n.retirement/100>24500)issues.push('retirement (2026 employee deferral exceeds the assumed $24,500 limit)');
 if(issues.length)return {status:'incomplete',issues:[...new Set(issues)]};
 const annualReceipts=p.netMode==='estimate'?n.gross*n.weeklyHours/40*n.paidWeeks/52:null,annualProfit=annualReceipts===null?null:annualReceipts-(p.workMode==='independent'?n.businessExpenses*12:0);
 const taxes=p.netMode==='estimate'?(p.workMode==='independent'?independentTaxes(annualProfit,n.retirement):employeeTaxes(annualReceipts,n.retirement)):null;
 const takeHome=taxes?taxes.monthly-n.health:n.manualNet;
 const mortgage=p.housingMode==='own'?loanPayment(n.homePrice*(1-n.downPercent/100),n.mortgageRate,n.mortgageYears*12):0;
 const property=n.homePrice?n.homePrice*n.propertyTax/1200:0,maintenance=n.homePrice?n.homePrice*n.maintenance/1200:0;
 const pmi=p.housingMode==='own'&&n.downPercent<20?n.homePrice*(1-n.downPercent/100)*n.pmiRate/1200:0;
 const housing=p.housingMode==='rent'?n.rent+n.utilities:mortgage+pmi+property+n.homeInsurance+n.hoa+maintenance+n.utilities;
 const carPayment=['used','new'].includes(p.carMode)?loanPayment(n.carPrice-n.carDown,n.carRate,n.carMonths):0;
 const transport=p.carMode==='transit'?n.transit+n.rides:carPayment+n.fuel+n.carInsurance+n.carMaintenance+n.carOther;
 const dining=n.quickCount*n.quickPrice+n.casualCount*n.casualPrice+n.specialCount*n.specialPrice;
 const rows=[['Housing & utilities',housing],['Transportation',transport],['Groceries',n.groceries],['Phone & internet',n.phone],['Household & personal care',n.household],['Debt payments',n.debt],['Dependents / other essentials',n.extraNeeds],['Cash savings',n.saving],['Meals out',dining],['Travel fund',n.travel],['Recreation',n.recreation],['Clothing fund',n.clothing]];
 const spending=rows.reduce((s,[,v])=>s+v,0),essential=rows.slice(0,7).reduce((s,[,v])=>s+v,0),remaining=takeHome-spending;
 const upfront=p.housingMode==='own'?n.homePrice*n.downPercent/100+n.homePrice*.03+(essential+(Number(p.health)||0))*6:null;
 return {status:'illustration',issues:[],annualReceipts,annualProfit,workMode:p.workMode,taxes,takeHome,housing,transport,carPayment,carUpfront:['used','new'].includes(p.carMode)?n.carDown:0,pmi,mortgage,property,maintenance,dining,rows,spending,remaining,essential,upfront,upfrontGap:upfront===null?null:Math.max(0,upfront-n.cashSaved),trips:n.tripPrice>0?n.travel*12/n.tripPrice:null,outings:n.outingPrice>0?n.recreation/n.outingPrice:null,items:n.itemPrice>0?n.clothing*12/n.itemPrice:null,rentBudget:takeHome-(spending-housing)-n.utilities};}
